  "Buyer": "买方",
  "By": "由",
  "By 2031: B2B software, merchant payments and export services could scale with reliable infrastructure and licences. By 2036: regional expansion needs strong retention and skilled teams. Returns depend on paying users and margins; test acquisition costs and cyber risk.": "由 2031：B2B 软件、商户支付和出口服务可凭借可靠基础设施和许可证实现规模化。由 2036：区域扩张需要强大的留存和熟练团队。回报取决于付费用户和利润率；测试获取成本和网络风险。",
  "By 2031: contracted supply, cold storage and processing could reduce losses and serve local buyers. By 2036: traceable, certified exports could expand. Model utilisation, yields and cash collection; crop disease, weather and commodity prices can reverse margins.": "由 2031：合同供应、冷链储存和加工可降低损失并服务本地买家。由 2036：可追溯、认证出口可扩大。模型利用率、产量和现金回收；作物疾病、天气和商品价格可能扭转利润率。",
  "By 2031: industrial buyers could adopt solar and storage where savings justify financing. By 2036: replication depends on bankable contracts and grid rules. Check buyer credit, permits, equipment FX costs and maintenance; utility payment risk can erase projected returns.": "由 2031：工业买家可在节省成本足以抵消融资时采用太阳能和储能。由 2036：复制取决于可融资合同和电网规则。检查买方信用、许可证、设备外汇成本和维护；公用事业付款风险可能抹去预期回报。",
  "By 2031: verified operators may need testing, engineering and equipment maintenance. By 2036: diversified supplier networks could expand if mineral projects proceed. Check licences, contracts, land, environmental obligations and gold-price sensitivity before investing.": "由 2031：经验证的运营商可能需要测试、工程和设备维护。由 2036：多元化供应商网络可在矿业项目推进时扩张。投资前请检查许可证、合同、土地、环境义务和金价敏感性。",
  "By 2031: warehousing, digital logistics and processing near trade corridors could lower costs. By 2036: regional exports need better connections and maintenance. Anchor customers, power costs and working capital determine returns; AfCFTA access is not automatic.": "由 2031：靠近贸易走廊的仓储、数字物流和加工可降低成本。由 2036：区域出口需要更好的连接和维护。核心客户、电费和营运资本决定回报；AfCFTA 访问并非自动。",
  "By card, in Ghana cedis. Ghanaian law doesn't allow us to price or charge in dollars, pounds or euros, so your bank converts the amount at its rate. Family members in Ghana can pay by mobile money.": "按卡支付，以加纳塞地计价。加纳法律不允许我们以美元、英镑或欧元定价或收费，因此您的银行将按其汇率转换金额。加纳的家庭成员可通过移动支付方式付款。",
