  "E-VAT is the GRA's electronic invoicing system for VAT-registered businesses. Each E-VAT receipt carries the Commissioner-General's signature, a QR code, an exact timestamp, a serial number and a machine registration code. The GRA offers a complete invoicing system free of charge, or a version that integrates with your existing software. You request it by writing to your Taxpayer Service Centre.": "电子增值税是加纳税务局（GRA）为增值税注册企业提供的电子发票系统。每张电子增值税收据都包含总干事签名、二维码、精确时间戳、序列号和机器注册码。GRA 提供完整的发票系统，免费使用，或提供与您现有软件集成的版本。您可通过向税务服务中心提交书面申请来获取。",
