  "Everything GEA, AfDB, EU and bank programmes typically ask for, gathered and checked before you apply.": "GEA、AfDB、欧盟和银行项目通常要求的所有资料，已在您申请前收集并核实。",
  "Everything a business needs": "企业所需的一切",
  "Everything in Brief": "简报中的所有内容",
  "Everything in Essentials": "Essentials中的一切",
  "Evidence and risks": "证据与风险",
  "Evidence you can": "您可以提供的证据",
  "Example": "示例",
  "Example of a visit report": "访问报告示例",
  "Example only · names and details invented": "仅为示例·姓名与细节均为虚构",
  "Exchange rates used on foreign currency invoices must reflect the prevailing market rates of commercial banks and be benchmarked against the BoG's published reference rate. In practice, state on the invoice the rate you used and its date, and keep a record of the BoG reference rate for that day.": "外币发票所用汇率必须反映商业银行的现行市场汇率，并以BoG公布的基准汇率为参照。实际操作中，请在发票上注明所用汇率及其日期，并保存该日BoG基准汇率的记录。",
  "Existing investors are protected by the transitional provisions. An enterprise or joint venture registered under Act 865 continues as if registered under the new Act, and its benefits and incentives are preserved (section 60). The new annual renewal cycle does, however, apply to everyone.": "现有投资者受过渡性规定保护。根据第865号法案注册的企业或合资企业将继续按新法案注册，其福利与激励措施得以保留（第60条）。但新的年度续期周期将适用于所有人。",
  "Existing investors: diarise the annual renewal, confirm technology transfer agreements are registered and review whether you qualify for more expatriate positions.": "现有投资者：记录年度续期，确认技术转让协议已注册，并审查您是否符合更多外籍职位的资格。",
  "Expatriate quotas": "外籍配额",
  "Expatriate quotas: more positions": "外籍配额：更多职位",
  "Expatriates (foreign nationals).": "外籍人士（外国国民）。",
  "Expect to provide passport copies for foreign directors and shareholders, consent letters, statutory declarations witnessed by a Commissioner for Oaths or notary public, the constitution, the share structure and a taxpayer identification number for each individual. The ORC's 2026 schedule lists:": "预计需为外国董事和股东提供护照复印件、同意书、经宣誓官或公证人见证的法定声明、公司章程、股权结构以及每位个人的纳税人识别号。ORC的2026日程列出：",
  "Explore": "探索",
  "Explore our practices": "了解我们的业务领域",
  "Explore published economic data, listed company performance and sector opportunities. Build your investment brief around verified evidence and clear risks.": "探索已发布的经济数据、上市公司业绩和行业机会。以经验证据和明确风险为基础构建您的投资简报。",
  "Export & AfCFTA readiness": "出口与AfCFTA准备",
