  "Exporters whose buyers ask for ESG evidence": "买家要求ESG证据的出口商",
  "Exports": "出口",
  "Exports 2025: $31.1bn, up from $19.1bn in 2024": "出口 2025：$31.1亿，较 2024 的 $19.1 亿增长",
  "Exports of goods and services are zero-rated for VAT. A service supplied to an overseas client may therefore carry no VAT, but only if it meets the conditions for an export. Confirm this with the Ghana Revenue Authority or your adviser, and issue the invoice through the E-VAT system if you are VAT-registered.": "货物和服务出口免征增值税。向海外客户提供的服务只有在满足出口条件时才可免税。请与加纳税务局或您的顾问确认，并在您已注册增值税的情况下通过 E-VAT 系统开具发票。",
  "Exports of goods and services are zero-rated, so no VAT is charged if the supply qualifies as an export. Confirm the conditions for your service with the GRA or your adviser.": "货物和服务出口免征增值税，若供应符合出口条件则不收增值税。请与 GRA 或您的顾问确认您的服务条件。",
  "Exports of goods and services are zero-rated; check that your export services meet the conditions.": "货物和服务出口免征增值税；请核实您的出口服务是否符合条件。",
