  "Five-year price change": "五年价格变动",
  "Fixed prices in Ghana cedis, excluding VAT where it applies. Hosting, WhatsApp and phone-call charges from providers are passed on at cost. Every project starts with a free 30-minute call.": "以加纳塞地固定价格，增值税适用时除外。托管、WhatsApp 与电话费用按成本转嫁。每个项目以一次免费的 30 分钟通话开始。",
  "Fixed quote": "固定报价",
  "Fixed scope,": "固定范围，",
