  "For Danish & Nordic investors": "面向丹麦及北欧投资者",
  "For German investors": "面向德国投资者",
  "For SWIFT payments, give your SWIFT/BIC and account number (Ghana does not use IBAN), agree who pays the charges, and verify any change of bank details by phone.": "如需SWIFT支付，请提供SWIFT/BIC及账号（加纳不使用IBAN），约定谁承担费用，并通过电话核实任何银行信息变更。",
