  "For families who want someone to see them in person.": "面向希望有人亲自照看的家庭",
  "For groups entering an African country: the legal entity, licences and approvals, local partners, recruiting the founding team, the first contracts and the systems to run it. Done before in DR Congo, Cameroon, Tanzania and other African markets.": "面向进入非洲国家的团体：法律实体、许可证与批准、当地合作伙伴、组建创始团队、首批合同及运营系统。已在刚果民主共和国、喀麦隆、坦桑尼亚及其他非洲市场完成。",
  "For individuals & diaspora": "面向个人及侨民",
  "For individuals & diaspora: start or invest without the stress": "面向个人及侨民：无压力启动或投资",
  "For investors": "面向投资者",
  "For investors from anywhere": "面向全球投资者",
  "For investors: enter Ghana with a local desk": "面向投资者：在当地设立办事处进入加纳",
  "For mining investors": "面向矿业投资者",
  "For mining investors: from concession to production, done properly": "面向矿业投资者：从特许权到生产，做到专业",
  "For paid events, pay by mobile money using the price and reference shown, then send us the transaction ID.": "如需付费活动，请使用移动支付支付显示的价格和参考号，然后将交易编号发送给我们。",
  "For parents living alone, or families with property to watch.": "面向单亲或有财产需要监管的家庭",
  "For parents who are well but need the paperwork handled.": "面向身体健康但需处理文件的父母",
  "For residents, the first GHS 588 a month is taxed at 0%, then rates rise through 5%, 10%, 17.5%, 25% and 30% to 35% above GHS 50,000 a month. Non-residents pay 25%.": "对于居民，首588GHS/月的收入按0%征税，随后税率依次上升至5%、10%、17.5%、25%和30%，直至超过50,000GHS/月后税率为35%。非居民的税率为25%。",
  "For trading companies the equity must now be in cash; reports indicate that capital in the form of imported goods no longer counts. The workforce rule has also changed. Instead of employing a minimum of 20 skilled Ghanaians, a foreign trading enterprise must ensure that at least 75% of its skilled employees are Ghanaian.": "对于贸易公司，股本必须以现金形式存在；报告显示，进口商品形式的资本已不再计入。劳动力规则亦已调整。外资贸易企业须确保至少75%的技术工人为加纳籍，而非最低雇佣20名技术工人。",
  "For your business": "为您的业务",
  "Foreign currency pricing is banned in areas such as domestic contracts, real estate, vehicles, school fees, hotels, airline tickets, retail and online sales.": "在国内合同、房地产、车辆、学费、酒店、机票、零售及网络销售等领域，禁止使用外币定价。",
  "Foreign currency proceeds must be paid into a Foreign Exchange Account (FEA) with a licensed bank, and exchange rates must reflect commercial bank market rates benchmarked to the Bank of Ghana reference rate.": "外币收益必须存入持牌银行的外汇账户（FEA），并且汇率需以商业银行市场汇率为基准，参照加纳银行参考汇率。",
  "Foreign investors can hold reconnaissance and prospecting licences and mining leases through a Ghanaian company; small-scale mining licences are reserved for Ghanaian citizens.": "外资可通过加纳公司持有勘探与勘查许可证及矿业租赁；小规模采矿许可证仅限加纳公民。",
