  "Free tools for every business in Ghana: a business health check, a funding finder and a VAT and E-VAT check. No sign-up.": "加纳每家企业免费工具：企业健康检查、融资查找器以及增值税和电子增值税检查。无需注册。",
  "Free tools tell you where you stand. The brief keeps you current. The forums put you in the room. We only charge when you want us to do the work.": "免费工具帮助您了解当前状况，简报为您提供最新动态，论坛让您有机会与行业人士交流。只有在您委托我们提供服务时，我们才会收费。",
