  "GHS 175 for each annual return, due first within 18 months of incorporation and then yearly.": "每份年度申报需缴纳 GHS 175，首次缴纳期限为公司成立后 18 个月，随后每年缴纳。",
  "GHS 2,200 / visit": "GHS 2,200 / 访客",
  "GHS 585 for registration of the company, constitution, Form 3 and beneficial ownership profile;": "公司注册、章程、表格 3 及受益所有人资料的注册费为 GHS 585；",
  "GHS per 1 unit. Market mid-rates; banks, card issuers and brokers apply their own spreads and fees.": "每 1 单位 GHS。市场中位价；银行、卡发行商和经纪人自行加价并收取费用。",
  "GIPA Act 1173": "GIPA 法案 1173",
