  "General enquiry": "一般查询",
  "General minimum capital requirements for non-trading foreign-owned companies and joint ventures are gone; foreign trading enterprises need USD 500,000 in cash equity (down from USD 1 million) and at least 75% Ghanaian skilled staff.": "非交易型外资公司和合资企业的最低资本要求已取消；外贸企业需持有现金股本 USD 500,000（低于 USD 1 百万美元）并至少拥有 75% 的加纳技术人员。",
  "Generally yes. Since 1 January 2026, suppliers of services must register for VAT regardless of turnover unless the Commissioner-General permits otherwise.": "一般来说，是的。自2026年1月1日起，服务供应商无论营业额多少均须登记增值税，除非税务总局局长另有许可。",
  "Generally yes. Under Act 1151, suppliers of services must register regardless of turnover unless the Commissioner-General permits otherwise.": "一般是的。根据第 1151 条法案，服务供应商必须注册增值税，无论营业额如何，除非总干事另有许可。",
  "Geological Survey Authority": "地质调查局",
  "Geology first.": "地质第一",
  "Geology first. Our own technology.": "地质第一。我们自己的技术",
  "Geology-led concession screening, due diligence and mining licences in Ghana, with field data investors and banks can check before they commit.": "以地质为主导的特许权筛选、尽职调查和加纳矿业许可证，投资者和银行可在承诺前检查现场数据。",
  "Geology-led due diligence": "以地质为主导的尽职调查",
  "Geology-led due diligence, a clear licensing path and Ghanaian partners you can verify. Our team combines field geology, our own TERRA field app and Afri-MINEX geospatial platform, and 25 years of project delivery in Africa.": "以地质为主导的尽职调查，清晰的许可路径和可核实的加纳合作伙伴。我们的团队结合现场地质、我们自己的 TERRA 现场应用和 Afri-MINEX 地理空间平台，以及 25 年在非洲的项目交付经验。",
  "Geology-led due diligence, a clear licensing path and project documents that development finance institutions and banks can assess, for solar power, mining and infrastructure in Ghana.": "以地质为主导的尽职调查，清晰的许可路径和可供发展金融机构及银行评估的项目文件，适用于加纳的太阳能、矿业和基础设施。",
  "Geology-led screening and due diligence, and mine-site power, for investors and concession holders who need facts they can check. We know every formal route to get mining work done in Ghana, from first licence to production, and we work through it for you.": "以地质为主导的筛选和尽职调查，以及矿区电力，为需要可核实事实的投资者和特许权持有人提供服务。我们了解在加纳完成矿业工作的每一正式路径，从首次许可证到生产，并为您全程办理。",
  "Geospatial platform": "地理空间平台",
  "Geospatial platform · built, 134 automated tests": "地理空间平台 · 已构建，134 次自动测试",
  "Germany": "德国",
  "Get a website like this": "获取类似此网站",
  "Get in the room": "参与行业交流",
  "Get registered, compliant and ready for investors.": "注册、合规并为投资者做好准备。",
  "Get the brief": "获取简报",
  "Get the brief →": "获取简报 →",
  "Get your business in front of investors and buyers through features, roundtables, trade missions and showcases, and grow in a way that includes persons with disabilities.": "通过特色、圆桌会议、贸易使命和展示会，让您的企业面向投资者和买家，并以包含残障人士的方式实现增长。",
  "Get your company registered, your numbers in order and your story clear, so you can apply to programmes, banks and investors with documents that hold up to scrutiny.": "让您的公司注册、数字整理、故事清晰，以便在申请项目、银行和投资者时提供经得起审查的文件。",
  "Gets you paid": "让您获得报酬",
  "Getting to the doctor, and getting the right help at home.": "前往医生并在家中获得正确帮助。",
