  "In February 2026 the Minerals Commission revoked about 300 small-scale licences and announced action against fronting, where foreign interests use Ghanaian nominees to hold rights.": "在2026年二月，矿产委员会撤销了约300个小规模许可证，并宣布将对前置行为采取行动，即外国利益通过加纳提名人持有权利。",
  "In good spirits and asked after the grandchildren. Walked to church on Sunday with a neighbour. Would like a new pair of reading glasses: we can book the optician if you agree.": "心情愉快并询问孙辈们的情况。周日与邻居一起去教堂。想要一副新的阅读眼镜：如果你同意，我们可以预约验光师。",
  "In late August 2025 the Bank of Ghana (BoG) issued a notice to banks and the public on unauthorised foreign exchange transactions, under the Foreign Exchange Act, 2006 (Act 723). It restated that the Ghana cedi is the sole legal tender for domestic transactions, and that residents may not price, advertise, invoice or accept payment in foreign currency unless the BoG has specifically licensed them. The one practical exception for ordinary businesses is invoicing expatriates and non-residents, subject to conditions.": "在2025年八月下旬，Ghana银行（BoG）向银行和公众发出通知，关于根据《外汇法》2006（第723号法案）未经授权的外汇交易。它重申加纳塞地是国内交易的唯一法定货币，居民不得以外币定价、广告、开票或收款，除非BoG已专门授权。普通企业唯一的实际例外是向外籍人士和非居民开票，须满足条件。",
  "In partnership with": "与……合作",
  "In practice": "实际上",
  "In short": "要点",
  "In this example, a client who is a VAT withholding agent would pay GHS 10,550 (GHS 12,000 less GHS 700 and GHS 750) and give you two certificates. The example assumes income tax withholding applies to the fee before VAT; confirm the base with your adviser or the GRA. The GRA's withholding VAT guidance predates Act 1151, so check whether it has been updated. Payments to non-residents for services generally attract 20% withholding tax as a final tax.": "在此示例中，作为增值税代扣代理的客户将支付GHS10,550（GHS12,000减去GHS700和GHS750），并给你两份证书。示例假设所得税代扣适用于增值税前的费用；请与顾问或GRA确认基数。GRA的增值税代扣指南早于第1151号法案，因此请检查是否已更新。向非居民支付服务费用通常需按20%代扣税作为最终税。",
  "Income statement, balance sheet and cash flow linked in one model, built on assumptions you can defend.": "收入表、资产负债表和现金流量表在一个模型中链接，基于你可以辩护的假设。",
  "Income tax withholding: within 15 days after the end of the month.": "所得税代扣：在月末后15天内。",
  "Incorporate a company limited by shares with the Office of the Registrar of Companies (ORC): at least two directors, one ordinarily resident in Ghana, plus a qualified company secretary.": "在公司注册处（ORC）注册股份有限公司：至少两名董事，其中一名为加纳常驻居民，并配备合格的公司秘书。",
  "Incorporate a company limited by shares with the Office of the Registrar of Companies: at least two directors, one ordinarily resident in Ghana, and a qualified company secretary. See": "在公司注册处注册股份有限公司：至少两名董事，其中一名为加纳常驻居民，并配备合格的公司秘书。参见",
