  "Is your activity open to foreign owners? Six activities are reserved for Ghanaians under the GIPA Act, 2026, and foreign-owned trading companies need USD 500,000 in cash equity. See": "您的业务是否对外资开放？根据GIPA法案，2026项业务仅限加纳人，外资贸易公司需持有500,000美元现金股本。详见",
  "It depends on the type of school and the regulator's process. Send us a WhatsApp message with your plans and we will explain the steps.": "取决于学校类型和监管流程。请通过WhatsApp发送您的计划，我们将为您说明步骤。",
  "It depends on what you need. After a free 30-minute call you get a fixed quote in Ghana cedis, paid by mobile money.": "取决于您的需求。免费30分钟通话后，您将获得以加纳塞地计价的固定报价，支付方式为移动支付。",
  "It is a fixed-price 60-minute call, and the fee is credited to any follow-on work you give us.": "这是一次固定价格的60分钟通话，费用将计入您后续委托的任何工作。",
  "It is not legally enforceable, the fees are not tax-deductible, and banks cannot remit the fees without the GIPA registration certificate.": "它在法律上不可执行，费用不可抵税，银行在没有GIPA注册证书的情况下无法转移费用。",
