  "(Social Security and National Insurance Trust): register at a SSNIT branch with your certificate of incorporation, company regulations, local authority certificate, the directors' Ghana Card or passport, your TIN and your digital address. SSNIT issues an employer registration number, and each worker must be registered as soon as they are hired.": "（社会保险与国家保险信托）：在 SSNIT 分支机构使用公司注册证、公司章程、地方政府证明、董事的加纳身份证或护照、您的税号（TIN）和数字地址进行注册。SSNIT 将发放雇主注册号码，每位员工在被雇佣后必须立即注册。",
