  "A 30-minute call on WhatsApp is free. We tell you what you need, what it costs and how long it takes.": "在 WhatsApp 上的 30-分钟电话是免费的。我们会告诉您所需信息、费用与所需时间。",
  "A Ghanaian firm heading to Côte d'Ivoire": "一家前往科特迪瓦的加纳公司",
  "A Ghanaian partner and a foreign investor set up a company together. We prepare the GIPA registration and diarise the annual renewal so it is never missed.": "一位加纳合作伙伴与一位外国投资者共同设立公司。我们负责 GIPA 注册并记录年度续费，确保从不遗漏。",
  "A National Investment Registry and a one-stop shop.": "国家投资登记处与一站式服务中心",
  "A Nordic agri-food firm weighing Ghana": "一家评估加纳的北欧农食公司",
  "A UK investor has been offered a joint venture in Kumasi. We verify the partner's background and licences, visit the site and deliver a written risk report.": "一位英国投资者已被提供在库马西的合资机会。我们核查合作伙伴的背景和执照，实地考察并提交书面风险报告。",
  "A VAT-registered consultancy invoices a Ghanaian client GHS 10,000 before tax.": "一家已注册增值税的咨询公司向加纳客户开具税前GHS 10,000的发票。",
  "A beneficial ownership disclosure for each individual who ultimately owns or controls the company.": "对最终拥有或控制公司的每位个人进行受益所有权披露。",
  "A bill before Parliament would change gold royalties to a price-linked sliding scale. Until it is settled, we model both regimes for your project.": "一项议案将黄金特许权使用费改为与价格挂钩的滑动比例。待该议案通过前，我们为您的项目模拟两种制度。",
  "A boutique in Osu sells mostly through Instagram messages. An online shop lets customers choose, pay by MoMo and get a confirmation without back-and-forth.": "奥苏的一家精品店主要通过Instagram私信销售。在线商店让客户选择、使用MoMo支付并即时获得确认，无需来回沟通。",
