  "A bridge between business, government and": "商业、政府与……之间的桥梁",
  "A building-materials trader in Kumasi takes most payments by mobile money. Each month the statements are sorted into sales and expenses automatically, ready for the bookkeeper.": "库马西的一家建筑材料贸易商大部分付款通过移动支付完成。每月账单会自动按销售和费用分类，直接交给簿记员。",
  "A business health check, a funding finder and a VAT check. Free, and your answers stay on your phone.": "企业健康检查、融资寻找与增值税核查。免费，且您的答案保存在手机上。",
