  "A clear, honest plan that explains what you do, who buys from you and how you will use the money.": "一份清晰、诚实的计划，阐明您的业务、客户来源以及资金使用方式。",
  "A clear, mobile-friendly site that tells customers what you do and how to reach you.": "一份清晰、移动友好的网站，向客户说明您的业务并提供联系方式。",
  "A community programme with clear goals, a budget and a way to report on it.": "一个社区项目，设有明确目标、预算和报告机制。",
  "A company from Denmark wants to know if processing in Ghana makes sense. A briefing covers the rules and risks, then a feasibility study tests the numbers before they commit.": "一家丹麦公司想了解在加纳加工是否可行。简报涵盖相关法规与风险，随后进行可行性研究以验证数字后再做决策。",
  "A company secretary who meets the qualifications in section 211, for example a lawyer in good standing or a member of a recognised professional body.": "一名公司秘书符合第211条规定的资格，例如持有良好执业记录的律师或认可专业机构成员。",
  "A company work permit for a non-ECOWAS national costs USD 1,293 (GIS fee schedule effective 15 May 2025).": "非ECOWAS国家的公司工作许可证费用为USD 1,293（GIS费用表自2025年5月15日起生效）。",
  "A consultancy with its own email": "一家拥有自有邮箱的咨询公司",
  "A contractor near Tarkwa wants to support the local community properly. We design a CSR programme with the community's priorities, a budget and simple reporting.": "一名位于塔尔卡附近的承包商希望正确支持当地社区。我们根据社区优先事项设计CSR项目，制定预算并提供简易报告。",
  "A credit and financial-data platform built for African lenders, in several currencies and languages.": "一款为非洲贷方打造的信用与金融数据平台，支持多种货币与语言。",
  "A daughter in London worries about her mother's NHIS renewal. We handle the renewal, visit every month and send a short written report with photos.": "伦敦的一名女儿担心母亲的NHIS续费。我们负责续费、每月访问并发送包含照片的简短书面报告。",
  "A dealer in Techiman makes a short video advert for social media explaining a new seed variety, with voice-overs in English and Twi.": "Techiman的一名经销商为社交媒体制作短视频广告，解释一种新种子品种，配有英文和Twi配音。",
  "A developer plans solar power for an industrial buyer in a free zone. We organise the PPA, EPC and project documents so a development finance institution can assess them.": "一位开发商为自由区的工业买家规划太阳能发电。我们组织PPA、EPC及项目文件，以便开发性金融机构评估。",
  "A distributor preparing for tenders": "一家分销商正在准备投标。",
  "A familiar face, in their language, on a regular day.": "熟悉的面孔，用他们的语言，在平常的一天。",
  "A family in Houston is building a house they cannot see. Site visits with photo and video reports show what has been done before each payment.": "休斯顿的一户家庭正在建造他们看不见的房屋。现场访问配合照片和视频报告，展示每笔付款前已完成的工作。",
  "A family looking at scholarships abroad": "一家人正在考虑海外奖学金。",
