  "A popular chop bar in Kumasi wants more lunchtime customers. A short radio spot with a jingle and a Twi voice-over announces its new lunch offer.": "Kumasi的一家受欢迎的快餐店想吸引更多午餐客人。短暂的广播广告配以主题曲和Twi配音，宣布其新的午餐优惠。",
  "A practical review of how you collect, store and share personal data, with the policies to match.": "对个人数据的收集、存储与共享进行实务审查，并配套相应政策。",
  "A producer's buyers want evidence of where the ore comes from. Monthly site reports with photos and GPS data, and records in Afri-MINEX, give them a clear trail.": "生产者的采购方需要矿石来源的证据。每月的现场报告包含照片和 GPS 数据，并在 Afri-MINEX 中记录，可为其提供清晰的溯源路径。",
  "A registered office in Ghana, with a physical address and a digital address.": "在加纳设有注册办公地点，既有实体地址，也有数字地址。",
  "A report every time": "每次都提交报告。",
  "A retired couple in Accra want a will and clear papers for their land. We gather the documents and arrange the work with our partner lawyers.": "阿克拉的一对退休夫妇需要遗嘱和土地清晰文件。我们收集文件并与合作律师协调办理。",
  "A retired head teacher in Kasoa wants to open a small basic school. We handle the registration and licensing paperwork and set out what the regulator will expect.": "卡索亚的一位退休校长想开设一所小型基础学校。我们负责注册与许可文件，并说明监管机构的期望。",
  "A retired teacher opening a basic school": "退休教师开办基础学校。",
  "A seat is confirmed only when we confirm it, and for paid events only once payment is received.": "座位仅在我们确认后才算确认，付费活动仅在收到付款后才算确认。",
  "A shea exporter at a showcase": "在展会上展示的乳木果出口商。",
  "A shea processor in the Northern Region applies to a development lender. An ESG review against the IFC Performance Standards shows what to fix before the lender's own checks.": "北部地区的一家乳木果加工厂向发展贷款机构申请。对 IFC 绩效标准的 ESG 审查显示在贷款机构自身检查之前需要改进的地方。",
  "A short, well-structured deck that matches your plan and your numbers.": "一份简洁、结构良好的演示文稿，符合您的计划和数字。",
  "A small engineering firm moves from personal email accounts to addresses on its own domain, with the website and email hosted and backed up daily.": "一家小型工程公司将个人邮箱迁移至自有域名地址，网站和邮箱每日托管并备份。",
  "A small processor in the Bono Region wants to apply for an SME programme. We write the business plan and a 3-year model, and check every document on the list before the deadline.": "邦奥地区的一家小型加工厂想申请 SME 计划。我们撰写商业计划和 3 年模型，并在截止日期前核对清单上的每份文件。",
  "A solar developer preparing for a lender": "为贷款机构准备的太阳能开发商。",
  "A statutory investor grievance mechanism.": "法定投资者申诉机制。",
  "A supplier has emailed new bank details. What should I do?": "供应商已通过电子邮件发送新的银行信息。我该怎么办？",
  "A tidy picture of your borrowing history and repayment record, ready for a lender to review.": "一份整洁的借贷历史和还款记录，供贷款机构审阅。",
  "A trading business and its MoMo statements": "贸易业务及其 MoMo 账单。",
  "A training centre adding digital skills": "培训中心新增数字技能课程。",
  "A utility-scale solar farm in the Greater Accra Region, led on the ground by Uffe Carlson of Carlson Capital Ltd, Gotham Consult's partner, as Managing Director of the project company Orion Energy Ghana Ltd.": "位于大阿克拉地区的公用规模太阳能农场，由Carlson Capital Ltd的 Uffe Carlson 亲自现场领导，作为项目公司 Orion Energy Ghana Ltd 的董事总经理，Gotham Consult 的合作伙伴。",
  "A utility-scale solar project taken from an old licence to build-ready: EPC tender, permits, land, grid and PPA renewal.": "一项从旧许可证到建成就绪的公用事业规模太阳能项目：EPC 招标、许可证、土地、配电网和 PPA 续签。",
  "A vocational centre in Ho wants its instructors to use digital tools in class. A staff workshop covers digital learning and practical AI skills.": "豪城的职业中心希望其讲师在课堂上使用数字工具。员工研讨会涵盖数字学习和实用 AI 技能。",
  "A voluntary tier 3 scheme is available on top.": "可在此基础上提供自愿级别 3 方案。",
  "A website or online shop that takes mobile money and card payments, with hosting, business email and daily backups looked after in Ghana.": "一个网站或在线商店，支持移动支付和卡支付，托管、商务邮箱及每日备份均在加纳负责。",
  "A website or online shop where customers can pay by mobile money or card, with hosting, business email and daily backups looked after, so you can focus on your customers.": "一个网站或在线商店，客户可通过移动支付或卡支付，托管、商务邮箱及每日备份均已妥善管理，您可专注于客户。",
  "A website that sells,": "一个销售网站，",
  "A women-led shea butter business from the Upper West Region presents its products at a showcase and meets buyers from other African markets.": "一家由女性领导的乳木果业务，来自西北地区，在展示会上展示其产品，并与来自其他非洲市场的买家会面。",
  "A working forum at Tang Palace Hotel, Accra. By invitation, free for SMEs, stakeholders and investors.": "在阿克拉唐宫酒店举行的工作论坛。仅限邀请，向中小企业、利益相关者和投资者免费开放。",
  "A written scope with a fixed fee in Ghana cedis.": "一份书面范围说明，收取固定费用，费用以加纳塞地计。",
  "A written scope with a fixed fee, so you know exactly what you are paying for.": "一份书面范围说明，收取固定费用，您将清楚了解所支付的具体内容。",
