  "Act 1173 replaced the GIPC Act in July 2026: minimum capital scrapped for most investors, new trading rules, annual renewal, six reserved activities and quotas.": "法案 1173 于 2026 年七月取代了 GIPC 法案：大多数投资者取消了最低资本要求，新增交易规则，年度续期，六项保留活动和配额。",
