  "Act 865 required foreign investors to bring in minimum equity before registering. Act 1173 removes the general requirement for most of them:": "法案 865 要求外国投资者在注册前带入最低股本。法案 1173 取消了大多数投资者的通用要求：",
  "Act 992 requires at least two directors, one of whom is ordinarily resident in Ghana. The test in the Act is residence rather than nationality, so take advice on who qualifies in your case.": "法案 992 要求至少两名董事，其中一名通常居住在加纳。法案中的测试是居住而非国籍，因此请就您的情况咨询合格人士。",
