  "An Accra-based business development and international projects consultancy, founded in 2018. We facilitate investment between the private sector and governments across Ghana, Nigeria, the UK, the US and Europe.": "一家总部位于阿克拉的业务发展与国际项目咨询公司，成立于2018。我们促进私营部门与加纳、尼日利亚、英国、美国及欧洲各国政府之间的投资。",
  "An agritech founder in Tamale needs working capital. We build the financial model, a credit profile and a pitch deck that tell the same story.": "一位塔马莱的农业科技创始人需要营运资金。我们构建财务模型、信用档案和演示文稿，呈现统一的故事。",
