  "An assessment against the IFC Performance Standards that many international lenders use, with a clear plan to close the gaps.": "对国际贷款机构常用的IFC绩效标准进行评估，并制定明确的弥补差距计划。",
  "An association of persons with disabilities in Kumasi arranges a business training workshop for members who want to start or grow a small enterprise.": "库马西残疾人协会为希望创办或扩展小型企业的会员安排业务培训工作坊。",
  "An association training its members": "协会为其会员提供培训",
  "An auditor who is a licensed chartered accountant registered with the Institute of Chartered Accountants, Ghana, and who has consented to act.": "一名持有加纳特许会计师协会注册执照的审计师，并已同意执业。",
  "An enterprise with foreign participation must register with GIPA after incorporation and before it starts operating. The Authority is required to complete registration within five days of receiving a complete application (section 34). Registration must then be renewed every year, instead of every two years as before. Legal commentators report administrative penalties of up to 7,000 penalty units for failure to renew (section 56), so put the renewal date in your compliance calendar. Establishing a branch also requires the Authority's written approval.": "一家外资参与的企业在注册成立后、开始运营前必须向GIPA注册。主管机关需在收到完整申请后五天内完成注册（第34条）。注册后须每年续期，取代以往的两年一次。法律评论员报告称，未续期将面临最高7,000处罚单位的行政处罚（第56条），请将续期日期纳入合规日历。设立分支机构亦需获得主管机关书面批准。",
  "An enterprise with foreign participation must register with GIPA after incorporation and before it starts operating. Under Act 1173 the Authority is to complete registration within five days of receiving a complete application, and registration must be renewed every year. GIPA lists the certificate of incorporation, a certified true copy of the constitution, Form 3 and the beneficial ownership document as core attachments. Registration also unlocks the automatic expatriate quota.": "一家外资参与的企业在注册成立后、开始运营前必须向GIPA注册。根据1173法案，主管机关需在收到完整申请后五天内完成注册，且注册须每年续期。GIPA将公司注册证书、章程的经认证真实副本、表格3及受益所有权文件列为核心附件。注册后亦可自动解锁外籍配额。",
  "An honest look at whether the market, the costs and the rules work for your plan.": "对市场、成本与规则是否适用于您的计划进行诚实评估。",
