  "Legal drafting and representation, audit, medical and nursing care, and licensed financial intermediation are carried out by qualified partner firms and practitioners, not by us. We coordinate that work and remain your point of contact.": "法律起草与代理、审计、医疗与护理以及持牌金融中介均由合格的合作伙伴公司和从业者执行，而非我们。我们负责协调该工作并保持为您的联络点。",
