  "Licence check against the mining cadastre, geology review, a site visit with TERRA field data, and land, community and illegal-mining checks.": "对矿业登记册进行许可核查，地质评估，配合TERRA现场数据进行现场考察，以及土地、社区和非法采矿检查。",
  "Licence check against the mining cadastre, geology review, site visit with TERRA field data, land, community and illegal-mining checks.": "对矿业登记册进行许可核查，地质评估，配合TERRA现场数据进行现场考察，土地、社区和非法采矿检查。",
  "Licence, geology and site checks, with field data from our TERRA app.": "许可、地质与现场检查，配合我们TERRA应用的现场数据。",
  "Licence, geology, site": "许可、地质、现场",
  "Licences, know-how, technical service and management agreements with foreign parties must be registered with GIPA. Under section 52, an unregistered agreement is not legally enforceable, its fees are not deductible for income tax, and banks cannot remit those fees without the registration certificate. If your Ghanaian company pays royalties or management fees abroad, check the registration status now.": "与外国方签订的许可、技术诀窍、技术服务和管理协议必须在GIPA注册。根据第52条，未注册的协议不具备法律强制力，其费用不计入所得税扣除，银行亦无法在未取得注册证书的情况下收取这些费用。如贵公司在加纳支付海外版税或管理费，请立即核查注册状态。",
