  "Month 2 handles tax, VAT, SSNIT, sector licences and the office lease; months 3 and 4 hire and train the team and set up payments and systems.": "第 2 个月处理税务、增值税、SSNIT、行业许可证和办公室租赁；第 3 与 4 个月招聘并培训团队，建立支付与系统。",
