  "Monthly sales, expense and cash summaries prepared automatically, ready for you and your accountant to check.": "每月销售、费用和现金摘要自动生成，供您和会计师检查。",
  "Monthly site reports with TERRA photo and GPS evidence, and provenance records in Afri-MINEX for buyers and ESG checks.": "每月现场报告，附TERRA照片和GPS证据，以及Afri-MINEX中的来源记录，供买家和ESG检查使用。",
  "Monthly visits to your parents, help with NHIS, pension and document renewals, and a written report with photos.": "每月访问您的父母，协助NHIS、养老金和文件续期，并提供带照片的书面报告。",
  "Monthly written report": "每月书面报告",
  "Monthly, in Ghana cedis": "每月，以加纳塞地计价",
  "Months 3 and 4: the team and the systems": "第3和4个月：团队与系统",
  "More about this": "更多信息",
  "More guides": "更多指南",
  "More photos from our events →": "更多活动照片 →",
  "Most SME money in Ghana now flows through programmes, compliance deadlines and government incentives. We prepare you for each one, so you qualify and stay compliant.": "目前加纳大部分中小企业资金通过项目、合规截止日期和政府激励流动。我们为每一项做好准备，使您符合资格并保持合规。",
  "Most chosen": "最受欢迎",
  "Most clients start free, join a forum, then move to a plan. Pay monthly with MTN MoMo, Telecel Cash or AirtelTigo Money. Cancel any time. Prices exclude VAT.": "大多数客户先免费试用，加入论坛，然后转为付费计划。通过MTN MoMo、Telecel Cash或AirtelTigo Money按月付款。随时取消。价格不含增值税。",
  "Most foreign investors set up a private company limited by shares under the Companies Act, 2019 (Act 992). An existing overseas company can instead register a Ghanaian branch as an external company. On the ORC's 2026 fee schedule, registering an external company costs USD 1,400 (payable in the cedi equivalent), against GHS 585 for a company limited by shares.": "大多数外国投资者在《公司法》2019（第992号法案）下设立股份有限公司。现有海外公司也可注册为外部公司。根据ORC的2026费用表，注册外部公司费用为USD 1,400（按塞地等值支付），相当于股份有限公司的GHS 585。",
  "Most foreign-owned businesses no longer face a general minimum capital; foreign trading companies need USD 500,000 in cash equity.": "大多数外国拥有的企业不再面临一般最低资本；外国贸易公司需持有USD 500,000现金股本。",
  "Most popular": "最受欢迎",
  "Most requested": "最常被请求",
  "Multi-factor sign-in and cryptographically signed documents": "多因素登录和加密签名文件",
  "Multilingual website, AI assistant, back office, events and payments in one system.": "多语言网站、AI 助手、后台、活动与支付一体化系统",
  "Must a new services company register for VAT straight away?": "新服务公司是否需要立即注册增值税？",
  "My company was registered under Act 865. Do I need to re-register?": "我的公司已根据法案 865 注册。是否需要重新注册？",
  "My consultancy has low turnover. Must I register for VAT?": "我的咨询业务营业额低。是否必须注册增值税？",
  "My mother is over 70. Does she still need to renew NHIS?": "我的母亲已超过 70 岁。她仍需续订 NHIS 吗？",
  "My parent lives outside Accra. Can you help?": "我的父母住在阿克拉以外。你能帮忙吗？",
  "MyJoyOnline: GIPC now an authority (22 July 2026)": "MyJoyOnline：GIPC 现为权威机构（2026年7月22日）",
  "MyJoyOnline: The GIPA Act, resetting Ghana's investment framework": "MyJoyOnline：GIPA 法案，重塑加纳投资框架",
  "NHIL": "NHIL",
  "NHIL and GETFund are recoupled with VAT, so registered businesses can deduct them as input tax.": "NHIL 与 GETFund 已与增值税重新耦合，已注册企业可将其作为进项税抵扣",
  "NHIS": "NHIS",
  "NHIS renewal (free for over-70s, but still yearly)": "NHIS 续订（超过 70 岁者免费，但仍需每年续订）",
  "Need a website that sells": "需要一个销售网站",
  "Need eyes on the ground": "需要地面监测",
  "Need funding": "需要融资",
  "Net pay": "净工资",
  "Never. We work through the formal application and consultation processes. Fees are for preparation and delivery, and any personal connection of our team to a public office is disclosed.": "从未。我们通过正式申请和咨询流程进行操作。费用用于准备和交付，任何团队成员与公共机构的个人关系均已披露。",
  "New": "新",
  "New 2026 VAT rules": "新 2026 增值税规则",
  "New FDI registered with GIPC": "新FDI已在GIPC注册",
  "New FDI registered, 2025": "新FDI已注册，2025",
  "New investor grievance procedure": "新投资者申诉程序",
  "New investors: check the reserved list and whether your activity counts as trading, then budget for incorporation, GIPA registration and sector licences.": "新投资者：请检查预留名单并确认您的业务是否属于交易，然后为公司注册、GIPA注册和行业许可证预留预算。",
  "New · Family Desk": "新 · 家庭桌",
