  "Other changes worth knowing": "值得了解的其他变更",
  "Other exports · 2025": "其他出口 · 2025",
  "Other family": "其他家庭",
  "Other practices": "其他实践",
  "Our fees are for preparation, advice and delivery. We never charge for access to a public official, and no part of any fee is a payment to influence a decision.": "我们的费用涵盖准备、咨询和交付。我们从不收取接触公共官员的费用，也没有任何费用部分用于影响决策",
  "Our flagship SME programme, run in Accra": "我们在阿克拉开展的旗舰中小企业项目",
  "Our forums are made possible by Ghanaian and international businesses who want to be where decisions get made. Mining houses, hotels, banks, law firms and logistics operators sit alongside the SMEs they serve.": "我们的论坛得益于加纳及国际企业的支持，这些企业希望置身决策之地。矿业公司、酒店、银行、律师事务所和物流运营商与其服务的中小企业并肩而立。",
  "Our investor desk.": "我们的投资者服务台。",
  "Our last programme,": "我们的上一次项目，",
  "Our partner": "我们的合作伙伴",
  "Our partner Carlson Capital Ltd": "我们的合作伙伴Carlson Capital Ltd",
  "Our partnership:": "我们的合作关系：",
  "Our price": "我们的价格",
  "Our prices": "我们的价格表",
  "Our promise": "我们的承诺",
  "Our rooms are working rooms. We ask attendees not to use them purely to sell, and to treat other guests with respect. We may decline admission, or ask someone to leave, where behaviour is abusive or where someone misrepresents who they are. Our events are inclusive by design, and we do not accept discrimination on any ground.": "我们的会议室是工作室。我们要求与会者不要仅仅用来推销，并且要尊重其他来宾。若行为粗暴或有人冒充身份，我们可能拒绝入场或要求其离开。我们的活动本着包容性设计，绝不接受任何形式的歧视。",
  "Our secure web platform that maps concessions, licence boundaries and field data in one place, so investors, partners and reviewers look at the same record.": "我们的安全网络平台将特许权、许可边界和现场数据集中映射，投资者、合作伙伴和评审者可查看同一记录。",
  "Our summaries of Ghanaian law, including the GIPA Act 2026 (Act 1173), tax rules and mining regulation, are general information, correct to the best of our knowledge on the date shown, and subject to change. Confirm your own position with the relevant authority or a qualified adviser.": "我们的加纳法律摘要，包括 GIPA 法案 2026（法案 1173）、税收规则和矿业监管，均为一般信息，按我们所知在所示日期内准确，且可能随时变更。请向相关主管部门或合格顾问确认您的具体立场。",
  "Our system opens every source every day. If a source changes, disappears or no longer says what we rely on, or a live figure moves, the team is told the same day.": "我们的系统每天开放所有来源。若某来源变更、消失或不再提供我们所依赖的信息，或实时数据发生变动，团队会在同一天获悉。",
  "Our systems require a password to reach personal data, access is limited by role, every change to a registration or a payment is logged with the person who made it, and traffic to our sites is encrypted. Payment identifiers are stored separately from the rest of your record. No system is perfect: if a breach affects you, we will tell you, and the Data Protection Commission, as Act 843 requires.": "我们的系统需要密码才能访问个人数据，访问权限按角色限制，每一次注册或付款变更都会记录下执行人，且我们网站的流量均已加密。支付标识符与其余记录分开存储。没有系统是完美的：若有泄露影响到您，我们将通知您，并按法案 843 的要求通报数据保护委员会。",
  "Our technology": "我们的技术",
  "Our ten practices": "我们的十项实践",
  "Our voice-first Android app for geological field work. Field teams capture readings by speaking, even offline, and every observation is checked on the spot.": "我们的语音优先 Android 应用用于地质现场工作。现场团队可通过语音（即使离线）记录读数，每一次观测都会即时核对。",
  "Outlook ratings are Gotham Consult's view for discussion, not investment advice.": "展望评级是 Gotham Consult 的讨论观点，而非投资建议。",
  "Over USD 10 million": "超过 USD 10 百万美元",
  "Overview of L.I. 2431 (Legal 500)": "L.I. 2431（法律 500）概览",
  "Owners of land or a house in Ghana who live elsewhere": "居住在国外的加纳土地或房屋所有者",
  "Owners tired of websites that break or go offline": "厌倦网站崩溃或离线的所有者",
  "Owners who want faster research before decisions": "希望在决策前更快完成研究的所有者",
  "PAYE monthly bands from 1 September 2026 start with the first GHS 588 at 0% and rise to 35% above GHS 50,000 (Income Tax (Amendment) Act, 2026).": "PAYE 月度税率从 2026年9月1日 开始，首个 GHS 588 的税率为 0%，并在 GHS 50,000 以上上升至 35%（《所得税（修订）法案》，2026）",
  "PAYE: 0 + 4.00 + 10.00 + 17.5% of 2,067": "PAYE：0 + 4.00 + 10.00 + 17.5% 的 2,067",
