  "Payments, software and services": "付款、软件和服务",
  "Penalties are heavier. Failure to register now attracts a minimum of three times the tax that should have been paid. Unregistered importers pay upfront VAT of 20% of the customs value, up from 12.5%.": "处罚更严厉。现在不注册将至少承担应缴税款的三倍。未注册进口商需预付20%的增值税，较之前的12.5%上升。",
  "Pension (SSNIT) is 18.5% of basic salary: 13% paid by the employer and 5.5% by the employee, due by the 14th of the following month.": "养老金（SSNIT）为基本工资的18.5%：雇主支付13%，雇员支付5.5%，应于下一个月的14日前缴纳。",
  "Pension, NHIS & document renewals": "养老金、NHIS及文件更新",
  "Pension, NHIS and document renewals": "养老金、NHIS及文件更新",
  "Pension, NHIS and document renewals, check-in visits and property watch, with a written report and photos after every visit. From GHS 2,400 a month.": "养老金、NHIS及文件更新、签到访问和物业监控，每次访问后提供书面报告和照片。每月从GHS 2,400 起。",
  "People starting a private school or training centre": "开办私立学校或培训中心的人",
  "People who want a will and estate papers in order": "需要遗嘱和遗产文件的人",
  "Permits and environment.": "许可证和环境",
  "Permits, partners and power, then monthly site reports once work begins.": "许可、合作伙伴与电力，随后在工作开始后每月提供现场报告。",
