  "Photos and video: Gotham Consult. If you appear here and would rather not, email us and we remove it.": "照片与视频：Gotham Consult。如您出现在此处且不愿意，请发送邮件给我们，我们将删除相关内容。",
  "Photos from the last Business Boot Camp": "上一次商业训练营的照片",
  "Pick a day and a time, Accra time (GMT). We confirm by WhatsApp or email, usually the same day.": "选择日期和时间，使用加纳阿克拉时间（GMT）。我们通常在同一天通过WhatsApp或邮件确认。",
  "Pick a practice, or tell us your goal on WhatsApp and we put the right team on it.": "选择一个实践领域，或在WhatsApp上告诉我们您的目标，我们将为您安排合适的团队。",
  "Pick your path. Fixed prices in cedis, paid by mobile money, and the first step is always free.": "选择您的路径。固定价格以塞地支付，使用移动支付，首步始终免费。",
  "Pick your path. You'll see what we solve, fixed prices you can pay with mobile money, and the first step, which is always free.": "选择您的路径。您将看到我们解决的问题，固定价格可使用移动支付，首步始终免费。",
  "Pilot phase 2026": "试点阶段 2026",
  "Pitch deck": "演示文稿",
  "Plan & price": "计划与定价",
  "Plan your year": "规划您的年度",
  "Plans": "计划",
  "Plans are priced in Ghana cedis, as Ghanaian law requires. You pay by card from anywhere and your bank converts the amount. Relatives in Ghana can pay by mobile money.": "计划以加纳塞地计价，符合加纳法律要求。您可随时使用银行卡支付，银行将进行货币转换。加纳亲属可使用移动支付。",
  "Platforms built with AI and run for the client: credit and financial data (Universal Credit Hub, for 54 African countries), payment-ready websites, and this website and back office.": "使用AI构建并为客户运营的平台：信用与金融数据（Universal Credit Hub，覆盖 54 个非洲国家）、已准备好支付的网站，以及本网站和后台管理系统。",
  "Play answer": "播放答案",
  "Please add the country code, e.g. +44 7700 900123.": "请添加国家代码，例如 +44 7700 900123。",
  "Please check the number. It looks too short or too long.": "请检查号码。它看起来太短或太长。",
  "Please choose a country.": "请选择国家。",
  "Please choose a region.": "请选择地区。",
  "Please choose at least one, or \"Not sure yet\".": "请至少选择一个，或选择“尚未确定”。",
