  "Practical guides for investors and companies: company registration, hiring, mining licences, opening an office, the GIPA Act 2026, Ghana VAT and getting paid from abroad. Each one lists its sources.": "面向投资者和企业的实用指南：公司注册、招聘、矿业许可证、办公场所设立、GIPA法案 2026、加纳增值税及海外收款。每项均列出来源。",
  "Practical help for older people in Ghana and families abroad.": "为加纳老年人及海外家庭提供实用帮助。",
  "Practical help for older people in Ghana and peace of mind for families abroad: renewals handled, regular visits, property looked after and estate paperwork in order, with written reports and photos.": "为加纳老年人提供实用帮助，并为海外家庭提供安心：续签办理、定期探访、财产维护及遗产文件整理，附书面报告与照片。",
  "Practical sessions where your staff learn to use AI on their own real tasks, safely and sensibly.": "实用课程，让您的员工在真实任务中安全、合理地使用人工智能。",
  "Practical training that helps teachers improve day-to-day lessons.": "实用培训，帮助教师提升日常教学。",
  "Practical, sourced guides for investors and companies: registering a company in Ghana, the GIPA Act 2026, Ghana VAT and foreign-currency invoicing.": "面向投资者和企业的实用、来源可靠的指南：在加纳注册公司、GIPA法案 2026、加纳增值税及外币发票。",
