  "Price:": "价格：",
  "Prices are fixed in Ghana cedis and paid by mobile money. If you live abroad, send us a WhatsApp message and we will agree the easiest way to pay.": "价格以加纳塞地计价，并通过移动支付支付。如您居住在海外，请发送 WhatsApp 消息给我们，我们将协商最便捷的支付方式。",
  "Prices are shown in the currency stated, in Ghana cedis or United States dollars. Where a price is shown in a foreign currency, payment in cedis is converted at our rate on the day of invoice.": "价格以所述货币显示，或以加纳塞地或美元计价。若价格以外币显示，支付时以发票日的汇率将塞地转换。",
  "Prices exclude VAT (20% in total: 15% VAT, 2.5% NHIL, 2.5% GETFund) and government and regulator fees, which are paid at cost. The first call is always free.": "价格不含增值税（20% 总计：15% 增值税，2.5% NHIL，2.5% GETFund）及政府和监管机构费用，后者按成本支付。首次通话始终免费。",
  "Prices exclude government and regulator fees, and exclude VAT where it applies; VAT is shown on the invoice. General guidance only, based on public rules current at 24 September 2026, and not legal, tax or investment advice. Your answers stay in your own browser and are not sent to us unless you choose to send them. Always confirm with the agency concerned, such as the GRA, the Registrar of Companies or GIPA; we check the details for you before you act.": "价格不含政府和监管机构费用，且不含适用增值税；增值税将在发票上显示。仅为一般指导，基于 2026年9月24日 时公开规则，并非法律、税务或投资建议。您的答案仅保存在您自己的浏览器中，除非您选择发送，否则不会发送给我们。请始终与相关机构（如 GRA、公司注册处或 GIPA）确认；我们在您行动前为您核实细节。",
  "Prices in Ghana cedis, excluding VAT (20% in total: 15% VAT, 2.5% NHIL, 2.5% GETFund). Government and regulator fees are paid at cost.": "价格以加纳塞地计价，未含增值税（20% 总计：15% 增值税，2.5% NHIL，2.5% GETFund）。政府和监管机构费用按成本支付。",
  "Pricing, certificates of origin, logistics and buyer introductions across Africa.": "在非洲范围内提供定价、原产地证书、物流及买家介绍服务。",
