  "Proceeds of foreign currency invoices must be paid into a Foreign Exchange Account (FEA) with a licensed bank in Ghana. Banks offer more than one type of foreign currency account, and the rules on what may be credited and withdrawn differ, so ask your bank to confirm that the account on your invoice is the right one for this purpose.": "外币发票的收益必须存入加纳持牌银行的外汇账户（FEA）。银行提供多种外币账户类型，关于可入账和可提取的规则各不相同，请向银行确认发票所列账户是否适用于此目的。",
