  "Reconnaissance, prospecting and mining leases in Ghana: who grants them, the 10% state interest, the 2026 gold royalty scale and what foreigners cannot do.": "加纳的侦察、勘探和矿业租赁：谁授予，10%的国家利益，2026黄金特许权费比例以及外国人不能做的事",
  "Record gold earnings, and lithium now open. Best entry: large-scale licences, JVs with verified Ghanaian partners, and mining services.": "记录黄金收益，锂矿现已开放。最佳进入方式：大型许可证、与已验证的加纳合作伙伴的合资企业以及矿业服务",
