  "Register and licence a school or training centre in Ghana, strengthen teaching and prepare staff for digital learning, with the paperwork handled.": "在加纳注册并许可学校或培训中心，强化教学并为数字学习准备员工，所有文件处理由我们完成。",
  "Register and licence a school or training centre, strengthen your teaching and prepare staff for digital learning, with the paperwork handled so you can focus on students.": "注册并许可学校或培训中心，强化教学并为数字学习准备员工，所有文件处理由我们完成，让您专注于学生。",
  "Register as an employer with SSNIT and with the GRA for PAYE before the first payroll.": "在SSNIT和GRA注册为雇主并在首次工资发放前完成PAYE。",
  "Register as an employer with SSNIT.": "在SSNIT注册为雇主。",
  "Register at gothamconsult.com/register with just your name and WhatsApp number.": "在gothamconsult.com/register仅使用您的姓名和WhatsApp号码注册。",
  "Register for a Gotham Consult forum, membership or investor briefing. Mobile money, card or invoice.": "注册Gotham Consult论坛、会员或投资者简报。移动支付、银行卡或发票。",
  "Register for a forum": "注册论坛。",
  "Register in a minute.": "一分钟完成注册。",
  "Register my business": "注册我的企业。",
  "Register someone else": "为他人注册。",
  "Register the company with the Office of the Registrar of Companies, register it with the Ghana Investment Promotion Authority (GIPA), open a bank account and register for tax with the Ghana Revenue Authority. Sector licences come on top where your activity needs one. We handle the whole path and report to you in writing.": "在公司注册处注册公司，在加纳投资促进局（GIPA）注册，开设银行账户并在加纳税务局（GRA）注册纳税。若业务需要行业许可证，则另行办理。我们负责整个流程并以书面形式向您汇报。",
  "Register via WhatsApp": "通过WhatsApp注册。",
  "Register via email": "通过电子邮件注册。",
  "Register with the Ghana Investment Promotion Authority (GIPA) after incorporation and before you start operating, then renew every year.": "在公司成立后、开始运营前在加纳投资促进局（GIPA）注册，然后每年续期。",
  "Register with the Ghana Investment Promotion Authority (GIPA) before you start operating. GIPA registration is renewed every year.": "在开始运营前在加纳投资促进局（GIPA）注册。GIPA注册每年续期。",
  "Register with the Ghana Revenue Authority for tax and, where required, VAT. Suppliers of services must register for VAT regardless of turnover. See": "在加纳税务局（GRA）注册纳税，并在需要时注册增值税。服务供应商无论营业额如何都必须注册增值税。请参阅",
  "Register your company with GIPA and get investor-ready in Ghana: registration, financial documents and a clear story for banks, programmes and investors.": "在加纳投资促进局（GIPA）注册您的公司，成为投资者准备就绪：注册、财务文件以及为银行、项目和投资者提供清晰的故事。",
  "Register · Gotham Consult": "注册 · Gotham Consult",
  "Registered, verified, visited": "已注册、已验证、已访问",
  "Registering a business name (sole proprietorship) costs GHS 130.": "注册个体经营名称费用为GHS 130。",
  "Registering a company limited by shares costs GHS 585 (with constitution, Form 3 and beneficial ownership profile) plus 1% capital duty on stated capital.": "注册股份有限公司费用为GHS 585（含章程、表格 3 及受益所有人资料），并需缴纳1%的资本税。",
  "Registration": "注册",
  "Registration and annual renewal": "注册及年度续费",
  "Registration form": "注册表格",
  "Registration is due within five days of a complete application but must now be renewed every year.": "注册需在完整申请后五天内完成，但现在必须每年续费。",
  "Registration number": "注册号",
  "Registration received": "已收到注册",
  "Registration status.": "注册状态。",
  "Registration within five days": "五天内完成注册",
  "Registration, GIPA Act 1173 compliance, a clear business plan.": "注册、GIPA法案 1173 合规、清晰的商业计划。",
  "Registration, business plans, pitch decks": "注册、商业计划、推介资料",
  "Registration, due diligence, market entry, mining and compliance. Fixed scope, fixed fee.": "注册、尽职调查、市场准入、矿业与合规。固定范围，固定费用。",
  "Registration, regulator licensing and the paperwork to run a school or training centre properly.": "注册、监管机构许可及正确运营学校或培训中心所需的文件。",
  "Registrations, permits, tax, staff": "注册、许可证、税务、员工",
  "Regular forums for SME owners, investors and partners. Register in a minute: we send the price and mobile money details to your WhatsApp, and confirm your seat as soon as payment arrives.": "为中小企业主、投资者和合作伙伴定期举办论坛。一分钟完成注册：我们将价格和移动支付详情发送至您的WhatsApp，并在付款到账后立即确认您的席位。",
  "Regular visits to your parents or relatives, with a written report and photos after each one.": "定期探访您的父母或亲属，每次探访后提供书面报告和照片。",
  "Regulated activities, such as financial services, telecommunications, energy, mining or food and drugs, need a licence from the relevant regulator before trading starts. Your local assembly may also require a business operating permit. Build these into your timeline, as they often take longer than incorporation itself.": "受监管的业务，如金融服务、电信、能源、矿业或食品与药品，需在交易开始前获得相关监管机构的许可证。当地议会也可能要求营业执照。请将这些纳入您的时间表，因为它们往往比公司注册更耗时。",
  "Regulatory watch": "监管监测",
  "Related": "相关",
  "Renew GIPA registration every year.": "每年续签 GIPA 注册。",
  "Renewable energy": "可再生能源",
  "Renewal happens in the pensioner's birth month: at a branch, a partner bank, through the SSNIT app with face verification, or by home verification for people who can't travel. Your parent has to take part in person, so it can't be done from London or Houston. We make sure it happens, every year, on time.": "续签在退休人员出生月份进行：可在分行、合作银行、通过 SSNIT 应用程序进行人脸验证，或对无法出行者进行居家验证。您的父母必须亲自参与，无法从伦敦或休斯顿完成。我们确保每年准时完成。",
  "Renewals and paperwork": "续签与文件处理",
  "Renewals calendar: SSNIT, NHIS, Ghana Card, bills": "续签日历：SSNIT、NHIS、加纳卡、账单",
