  "Shares offer access to established businesses and potential dividends. Over five or ten years, earnings, entry valuation, liquidity and FX matter more than last year’s rally. Use a licensed broker; agree custody, fees, taxes and repatriation arrangements before funding.": "股票提供进入成熟企业和潜在股息的通道。五年或十年期间，收益、入场估值、流动性和外汇比去年的反弹更为重要。请使用持牌经纪人；在资金投入前就托管、费用、税费和汇回安排达成一致。",
  "Shops and brands that want to sell online": "想在线销售的商店和品牌",
  "Shops, restaurants and service businesses advertising locally": "本地广告的商店、餐厅和服务型企业",
  "Short videos for social media and screens, built around your product.": "围绕您的产品制作的短视频，适用于社交媒体和屏幕播放",
  "Short, memorable tunes that carry your name and message.": "简短、易记的旋律，传递您的品牌名称和信息",
  "Sign the office lease and fit out the office.": "签署办公室租赁合同并进行办公室装修",
  "Since 1 January 2026 it is 20%: VAT at 15% plus NHIL and GETFund at 2.5% each, all on the same base. The 21.9% figure applied before the reform.": "自2026年1月1日起，税率为20%：增值税15% 加 NHIL 与 GETFund 各2.5%，均以同一基数计税。21.9% 的数字是改革前的数值。",
  "Since 1 January 2026, VAT is 15% plus NHIL 2.5% and GETFund 2.5% on the same base: 20% in total (VAT Act 2025, Act 1151).": "自2026年1月1日起，增值税为15% 加 NHIL 2.5% 与 GETFund 2.5% 以同一基数计税：总计 20%（增值税法 2025，法案 1151）。",
  "Since 1 January 2026, businesses that supply services must register for VAT whatever their turnover, unless the Commissioner-General permits otherwise. Suppliers of goods must register once taxable supplies exceed GHS 750,000 in a 12-month period. VAT-registered businesses issue invoices through the GRA's certified invoicing system (E-VAT) or a fiscal electronic device.": "自2026年1月1日起，提供服务的企业必须注册增值税，无论其营业额如何，除非总干事另有许可。货物供应商在税前供应额超过 GHS 750,000 的 12 个月期间后须注册。已注册增值税的企业通过 GRA 的认证电子发票系统（E-VAT）或财政电子设备开具发票。",
  "Since 1 January 2026, the VAT Act, 2025 (Act 1151) applies VAT at 15%, NHIL at 2.5% and GETFund at 2.5% on the same base: 20% in total, down from an effective 21.9%.": "自2026年1月1日起，增值税法 2025（法案 1151）适用增值税 15%，NHIL 2.5% 与 GETFund 2.5% 以同一基数计税：总计 20%，低于有效 21.9%。",
  "Since March 2026 (L.I. 2517) the gold royalty runs on a sliding scale from 5% at USD 1,900 an ounce or less to 12% above USD 4,500.": "自 2026 年三月（L.I. 2517）起，金矿特许权费按滑动比例计费，低于每盎司 USD 1,900 时为 5%，超过 USD 4,500 时为 12%。",
  "Since March 2026 it follows a sliding scale tied to the gold price, from 5% at USD 1,900 an ounce or less up to 12% above USD 4,500 an ounce.": "自 2026 年三月起，金矿特许权费按滑动比例与金价挂钩，低于每盎司 USD 1,900 时为 5%，高于每盎司 USD 4,500 时为 12%。",
  "Site monitoring & provenance": "现场监测与溯源",
  "Site visits with photo and video reports on your house, building work or land while you are away.": "在您不在时，对您的住宅、建筑工程或土地进行现场访问并提供照片和视频报告",
  "Site visits with photo and video reports while your house or business is built.": "在您的住宅或企业建设期间进行现场访问并提供照片和视频报告",
  "Six activities remain reserved for Ghanaians, expatriate quotas now run from 2 to 12, and unregistered technology transfer agreements are unenforceable.": "六项活动仍保留给加纳人，外籍配额现从 2 计至 12，未注册的技术转让协议不可执行。",
  "Six activities stay reserved for Ghanaians,": "六项活动仍保留给加纳人，",
  "Six categories: market and petty trading, beauty salons and barbering, taxi and car hire with fewer than 25 vehicles, exercise books and basic stationery, retail of finished pharmaceuticals, and sachet water.": "六类：市场与小额贸易、美容沙龙与理发、出租车与汽车租赁（车辆数少于 25）、练习本与基础文具、成品药品零售以及袋装水。",
  "Six months is a realistic time to go from a decision to a working office in Ghana with registered company, bank account, licences, staff and first sales.": "六个月是从决策到在加纳设立运营办公室的现实时间，已注册公司、银行账户、执照、员工和首笔销售均已完成。",
  "Sjoerd B. Gaastra, his manager for more than seven years · LinkedIn recommendation, 2009": "Sjoerd B. Gaastra，七年以上的经理 · LinkedIn 推荐，2009",
  "Skip to content": "跳转至正文",
  "Small sessions where business owners and investors meet and talk directly.": "小型会议，企业主与投资者直接会面并交流。",
  "Small-scale gold": "小规模黄金",
  "Small-scale mining": "小规模采矿",
  "Small-scale mining licence": "小规模采矿许可证",
  "Small-scale mining licences are for Ghanaian citizens only. Engaging a foreigner in illegal small-scale mining is an offence carrying heavy fines and prison terms. The lawful routes for a foreign investor are its own reconnaissance or prospecting licence or mining lease, held through a company incorporated in Ghana, or buying gold through GoldBod. Any financing, equipment or partnership deal with a small-scale licence holder needs Ghanaian legal advice first.": "小规模采矿许可证仅限加纳公民。雇佣外国人从事非法小规模采矿构成犯罪，可能面临高额罚款和监禁。外国投资者的合法途径包括自行侦察或勘探许可证、通过在加纳注册的公司持有采矿租赁，或通过GoldBod购买黄金。与小规模许可证持有人进行任何融资、设备或合作协议前，需先获得加纳法律咨询。",
  "Social media": "社交媒体",
  "Software & apps": "软件与应用",
  "Software · Ghana": "软件 · 加纳",
  "Solar IPPs, PPAs & EPC": "太阳能IPPs、PPA与EPC",
  "Solar and renewable energy": "太阳能与可再生能源",
  "Solar developers and independent power producers": "太阳能开发商与独立发电商",
  "Solar for industry and free zones, mini-grids and storage. Strongest with private buyers of power.": "工业与自由区、微电网与储能的太阳能。最强与私营电力买家合作。",
  "Sole proprietorship or Ltd with the Registrar, TIN and first steps.": "在注册处登记为个体经营或有限公司，获取税号并完成首步操作。",
  "Some events are open and others are by invitation. Where an event is by invitation, submitting the form is an application rather than a booking, and we may accept or decline it at our discretion.": "部分活动公开，部分仅限邀请。若为邀请制活动，提交表单即为申请而非预订，我们可自行决定是否接受。",
  "Some forums are open, some by invitation. Invitation-only forums confirm your place after a short review.": "部分论坛公开，部分仅限邀请。仅限邀请的论坛在简短审核后确认您的席位。",
  "Some of our providers may process or store data outside Ghana. When AI support is enabled, recent chatbot messages are sent to the AI service configured for this site through its API and may be processed outside Ghana, subject to provider and account settings. For EU and UK clients, we apply GDPR standards.": "我们的部分服务商可能在加纳以外处理或存储数据。启用AI支持时，最近的聊天机器人消息会通过本网站配置的AI服务API发送至该服务，可能在加纳以外处理，受服务商和账户设置约束。对欧盟和英国客户，我们遵循GDPR标准。",
