  "Where you tick the marketing box, to send you our business brief and forum announcements. You can stop this at any time.": "您勾选营销框后，将向您发送我们的业务简报和论坛公告。您可以随时停止此服务。",
  "Whether you are starting a business in Accra or investing from London, Hamburg or Houston: we register, verify and report, so you are never guessing.": "无论您是在阿克拉创业，还是从伦敦、汉堡或休斯顿投资：我们负责注册、核实和报告，让您不必猜测。",
