  "Who you may invoice in foreign currency in Ghana, where the money must go, which rate to use, and how to receive SWIFT payments safely and without surprises.": "您可以以外币在加纳开具发票的对象，款项应汇往何处，使用何种汇率，以及如何安全、无意外地接收SWIFT付款。",
