  "Your browser turns your voice into text (in Chrome this goes through Google's speech service). In English the receptionist speaks with the voice “Jenny (Dioco)”, made on our own server; in French and Spanish your browser reads the answers aloud. We do not store the call: the board on the right is cleared when you close the page. Please use an invented name and do not share real medical details. For emergencies in Ghana call 112.": "您的浏览器将语音转换为文本（在Chrome中通过Google的语音服务）。英文时接待员使用“Jenny (Dioco)”的声音，由我们自己的服务器生成；法语和西班牙语时浏览器会朗读答案。我们不存储通话记录：右侧的板块在您关闭页面时会被清除。请使用虚构姓名，勿透露真实医疗细节。若在加纳遇紧急情况，请拨打112。",
  "Your country": "您的国家",
