  "Your name, email, WhatsApp number and the country you live in; your relationship to the family member in Ghana, the region and town they live in, the languages they speak, the kind of help you are looking for, and a record of your consent. We do not ask for their name or for any health information on the website. Before any service starts we speak to them directly, and nothing proceeds without their agreement": "您的姓名、电子邮件、WhatsApp号码以及您所在国家；您与加纳家庭成员的关系、他们所在地区和城镇、他们使用的语言、您寻求的帮助类型，以及您的同意记录。我们不会在网站上询问他们的姓名或任何健康信息。在任何服务开始前，我们会直接与他们沟通，且未经他们同意不做任何后续操作。",
  "Your name, email, and if you give them your WhatsApp number and company or fund; the country you invest from, how you invest, your usual ticket size, the sectors and timing you are interested in, any message you write, and a record of your consent. We use it only to contact you about investment opportunities in Ghana and our investor events, and you can leave the list at any time": "您的姓名、电子邮件，以及如果您提供WhatsApp号码和公司或基金信息；您投资所在国家、投资方式、常规投资额度、感兴趣的行业和时机、任何您撰写的信息，以及同意记录。我们仅用于联系您关于加纳投资机会和我们的投资者活动，您可随时退订。",
