  "▶ Watch the last Boot Camp": "▶ 观看最后一次训练营",
  "min read": "分钟阅读",
  "Updated": "更新时间",
  "Two questions under the Ghana Investment Promotion Authority Act, 2026 (Act 1173) come first. Is your activity one of the six reserved for Ghanaians, such as market trading or taxi services with fewer than 25 vehicles? And is it trading? Foreign-owned trading enterprises must invest at least USD 500,000 in cash as equity and ensure that at least 75% of their skilled employees are Ghanaian. Most other foreign-owned companies and joint ventures no longer face a general minimum capital requirement, although sector regulators may set their own.": "根据《加纳投资促进法案》2026（法案 1173）的两项问题优先考虑。你的业务是否属于加纳人专属的六项之一，例如市场交易或少于 25 辆车辆的出租车服务？以及它是否为交易业务？外资交易企业必须以现金形式投资至少 USD 500,000 作为股本，并确保至少 75% 的技术员工为加纳人。大多数其他外资公司和合资企业已不再面临一般最低资本要求，尽管行业监管机构可自行设定。",
  "A new Minerals and Mining Bill was expected in Parliament from October 2026 and was not law on 1 October 2026.": "预计在 2026年10月 期间，议会将通过新的矿产与采矿法案，但截至 2026年10月1日 并未成为法律。",
  "After the 2022–23 debt crisis, Ghana is growing again: inflation at a multi-year low, record exports and investment flows rising. Here is the picture for investors, as of September 2026.": "经历2022—2023年债务危机后，加纳经济重回增长轨道：通胀降至多年低位，出口创下纪录，投资流入增加。以下为截至2026年9月的投资者概况。",
  "Citi Newsroom: How to register a business in Ghana and what foreign investors must know (April 2026)": "Citi 新闻中心：如何在 Ghana 注册公司以及外国投资者须知（2026年4月）",
  "ClientEarth: L.I. 2462 revoked (December 2025)": "ClientEarth：L.I. 2462 已被撤销（2025年12月）",
  "EY Ghana: Reference guide to the new VAT Act, 2025 (Act 1151), January 2026 (PDF)": "EY Ghana：新增值税法案参考指南，2025（法案 1151），2026年1月（PDF）",
  "First lithium mining lease ratified, March 2026": "首个锂矿租赁已获批准，2026年3月",
  "From April 2026, every SSNIT pensioner must renew once a year. Miss it and pension payments can stop.": "自 2026年4月 起，每位 SSNIT 退休金领取者每年必须续费一次。若错过，退休金支付可能停止。",
  "GSE 2024 factbook / December 2025 report": "GSE 2024 事实手册 / 2025年12月 报告",
  "GSE December 2025": "GSE 2025年12月",
  "Ghana's first lithium mining lease was ratified in March 2026.": "Ghana 首个锂矿租赁已于 2026年3月 获批。",
  "GhanaWeb: sliding-scale royalty regime (December 2025)": "GhanaWeb：分级版税制度（2025年12月）",
  "Inflation, August 2026": "通胀，2026年8月",
  "Lotteries and betting, and the printing of recharge scratch cards, are no longer on the list. Enforcement is tightening. In August 2026 GIPA and the Ghana Union of Traders' Associations agreed measures to protect the informal retail sector, and Graphic Online reported administrative penalties of 5,000 to 10,000 penalty units, plus 500 to 1,000 penalty units for each month a breach continues. \"Fronting\", where a Ghanaian lends their name to hide foreign ownership, is a specific target.": "彩票与博彩，以及充值刮刮卡的印制已不再列入清单。执法力度正在加强。在 2026年8月，GIPA 与 Ghana 联合商会同意采取措施保护非正规零售部门，Graphic Online 报道行政处罚为 5,000 至 10,000 处罚单位，且每月违规持续将追加 500 至 1,000 处罚单位。\"前置\"，即 Ghanaian 以其名义隐藏外国所有权，是特定打击目标。",
  "Minerals Commission: reforms to boost Ghanaian ownership (February 2026)": "矿产委员会：改革以提升 Ghanaian 所有权（2026年2月）",
  "Miningmx: Ghana mining bill seeks wider state powers (October 2026)": "Miningmx：Ghana 采矿法案寻求更广泛的国家权力（2026年10月）",
  "Orion Energy Ghana Ltd signed a power purchase agreement with the Electricity Company of Ghana in January 2016 for an earlier, smaller solar phase at Dawa. Extensions and amendments followed in 2017 and 2018, and a feasibility study was prepared for a 20 MWp first phase. After that, the project stood still for several years.": "Orion Energy Ghana Ltd 于 2016年1月 与 Ghana 电力公司签署电力采购协议，启动 Dawa 的早期小型太阳能阶段。随后在 2017 与 2018 进行了扩展与修订，并为 20 MWp 的首个阶段准备了可行性研究。之后，该项目停滞数年。",
  "Regulatory watch · September 2026": "监管监测 · 2026年9月",
  "SSNIT, December 2025": "SSNIT，2025年12月",
  "The Growth and Sustainability Levy on gold was cut from 3% to 1% of gross production in March 2026.": "黄金的增长与可持续性税从3%降至1%，占2026年3月年毛产量的比例。",
  "The State takes a 10% free carried interest, and since March 2026 gold royalties follow a sliding scale from 5% to 12% of the gold price.": "国家获得10%的免税携带收益，自2026年3月起，黄金版税按滑动比例从5%至12%的黄金价格计提。",
  "What are the PAYE rates in Ghana from September 2026?": "加纳的PAYE税率从2026年9月起是多少？",
  "cut from 3% to 1% of gross gold production in March 2026.": "从3%降至1%，占2026年3月年毛黄金产量的比例。",
  "since March 2026 (L.I. 2517) it runs from 5% at US$1,900 an ounce or less to 12% above US$4,500, and the growth and sustainability levy is 1%. A further mining bill that would widen state powers is under discussion; we follow it and model both for you.": "自2026年3月（L.I. 2517）起，税率从5%（US$1,900/盎司或以下）至12%（US$4,500以上），增长与可持续性税为1%。正在讨论进一步扩大国家权力的矿业法案；我们将跟踪并为您建模。",
  "since March 2026, under the Minerals and Mining (Royalties) Regulations, 2025 (L.I. 2517), the gold royalty rises with the gold price, from 5% at USD 1,900 an ounce or less to 12% above USD 4,500. Lithium has its own 5% to 12% scale, and other minerals stay at 5%. Some large miners with development agreements are reported to be exempt.": "自2026年3月起，根据《矿产与采矿（版税）条例》，2025（L.I. 2517），黄金版税随黄金价格上升，从5%（USD 1,900/盎司或以下）至12%（USD 4,500以上）。锂矿有其独立的5%至12%比例，其他矿物保持5%。部分大型矿业公司在开发协议下被报告为豁免。",
  "Phone, WhatsApp and your website, day and night, in English. A person takes over whenever the caller asks or the AI is unsure.": "电话、WhatsApp 及贵网站，全天候以英文服务。接线员在来电者要求或 AI 不确定时接手。",
