  "Gotham Consult and its partner Carlson Capital Ltd support mining investors from first screening to production. Field geology, our in-house digital platforms and formal licensing work sit in one team, so you get evidence you can check before you commit capital.": "Gotham Consult 及其合作伙伴 Carlson Capital Ltd 支持矿业投资者从初步筛选到投产的全过程。实地地质勘探、我们自有的数字平台以及正式许可办理工作由同一团队负责，因此您在投入资本之前可获得可核实的证据。",
  "Gotham Consult and its partner Carlson Capital Ltd support mining investors from first screening to production. Field geology, our own digital platforms and formal licensing work sit in one team, so you get evidence you can check before you commit capital.": "Gotham Consult 及其合作伙伴 Carlson Capital Ltd 支持矿业投资者从初步筛选到投产的全过程。实地地质勘探、我们自有的数字平台以及正式许可办理工作由同一团队负责，因此您在投入资本之前可获得可核实的证据。",
  "Gotham Consult back office": "Gotham Consult 后台",
