  "Gotham Consult delivers mining, technology, fintech and investor services together with Carlson Capital Ltd, a company registered in Ghana. Carlson Capital brings field geology, in-house software platforms and 25 years of project delivery across Africa and Europe.": "Gotham Consult 与在加纳注册的 Carlson Capital Ltd 共同提供矿业、技术、金融科技及投资者服务。Carlson Capital 提供实地地质勘探、内部软件平台以及在非洲和欧洲交付 25 年项目的经验。",
