  "The terms on which Gotham Consult and Carlson Capital Ltd provide this website, our forums and our advisory services in Ghana.": "Gotham Consult 和 Carlson Capital Ltd 在加纳提供本网站、我们的论坛及咨询服务所依据的条款。",
  "The text, design, reports, tools, photographs and video on this site belong to Gotham Consult and Carlson Capital Ltd, except where credited to someone else. Wikimedia photographs are used under the licences named on the main site. Some images, and the on-screen presenter, are generated with artificial intelligence and are labelled as such. Reports and deliverables we produce for you are yours to use in your business once paid for; the underlying methods, templates and tools remain ours.": "本网站上的文本、设计、报告、工具、照片和视频归 Gotham Consult 和 Carlson Capital Ltd 所有，除非注明归属于他人。维基媒体（Wikimedia）照片根据主站列明的许可证使用。部分图像及屏幕上的演示者由人工智能生成，并已作相应标注。我们为您制作的报告和交付成果，在您支付费用后，您可在您的业务中使用；但底层的 methodologies、模板和工具仍归我们所有。",
  "This forum is free for SMEs, stakeholders and investors. Send your details and we confirm your invitation, usually the same day. Seats are limited.": "本论坛对中小企业、利益相关方和投资者免费开放。请发送您的详细信息，我们将确认您的邀请，通常在同一天内完成。席位有限。",
