  "A company costs GHS 585 in registry fees plus 1% stamp duty on its stated capital (ORC, 2026 schedule). You need it for bank loans, contracts and most programmes.": "公司需支付 GHS 585 的注册费，以及按注册资本计算的 1% 印花税（依据 ORC，2026 附表）。申请银行贷款、签订合同及参与大多数项目均需此文件。",
  "We register it for you: GHS 1,500 plus registry fees": "我们为您办理注册：费用为 GHS 1,500 加上注册费",
  "Since 1 January 2026, businesses selling goods above GHS 750,000 a year must register for VAT (20% in total with NHIL and GETFund) and issue E-VAT invoices.": "自2026年1月1日年起，年销售额超过GHS 750,000的企业必须注册增值税（含NHIL和GETFund，总税率为20%），并开具电子增值税发票。",
  "We register it for you: GHS 2,400 plus registry fees": "我们为您办理注册：GHS 2,400 另加注册费",
  "E-VAT setup from GHS 2,900, filing from GHS 1,300/month": "电子增值税系统设置费 GHS 2,900 起，申报服务费 GHS 1,300/月起",
  "Registry fees (ORC, 2026 schedule): a business name (sole proprietorship) GHS 130; a company GHS 585 plus 1% stamp duty on its stated capital. You need it for bank loans, contracts and most programmes.": "注册费（ORC，2026 费率表）：个体工商户（独资经营）GHS 130；有限公司 GHS 585，另加注册资本1%的印花税。办理银行贷款、签订合同及参与大多数项目均需此注册。",
  "Checked every week": "每周核查",
  "Our system opens every source each week. If a source changes, disappears or no longer says what we rely on, or a live figure moves, the team is told the same day.": "我们的系统每周都会打开所有信息源。若信息源发生变更、消失或不再包含我们所依赖的内容，或实时数据发生变动，团队将在当天收到通知。",
  "Business registration for Ghanaian owners": "加纳籍业主企业注册",
  "Sole proprietorship or Ltd for Ghanaian owners, with the Registrar, TIN and first steps.": "为加纳籍业主办理独资企业或 Ltd 注册，包括登记、TIN 及初期设立事项。",
  "Company registration for foreign owners": "外籍业主公司注册",
  "Fully remote: an Ltd company with the Registrar, 48-hour express filing, TIN and certificates by email. The law also requires a Ghana-resident director, a company secretary and a Ghana office: yours, or ours on request.": "全程远程办理：在登记机构注册 Ltd 公司、48 小时加急申报、TIN 及通过电子邮件交付证书。法律还要求加纳常驻董事、公司秘书和加纳办公地址：可由您自行提供，也可按需由我们提供。",
  "all-in: government fees, express filing and VAT": "全包：政府费用、加急申报和 VAT",
  "Courier, travel, accommodation, notary and translation costs are not included and are billed at cost, after your approval.": "费用不包含快递、差旅、住宿、公证和翻译费用；这些费用在您批准后按实际成本收取。",
  "Only need the company registered, from abroad? Company registration for foreign owners: USD 1,450 all-in, fully remote.": "只需从境外办理公司注册？外籍业主公司注册：USD 1,450 全包，全程远程办理。",
  "Prices in Ghana cedis, excluding VAT (20% in total: 15% VAT, 2.5% NHIL, 2.5% GETFund). Government and regulator fees are paid at cost. Courier, travel, accommodation, notary and translation costs are not included and are billed at cost, after your approval.": "价格以加纳塞地计价，不含 VAT（合计 20%：15% VAT、2.5% NHIL、2.5% GETFund）。政府及监管机构费用按实际成本收取。 费用不包含快递、差旅、住宿、公证和翻译费用；这些费用在您批准后按实际成本收取。",
  "Prices exclude VAT (20% in total: 15% VAT, 2.5% NHIL, 2.5% GETFund) and government and regulator fees, which are paid at cost. The first call is always free. Courier, travel, accommodation, notary and translation costs are not included and are billed at cost, after your approval.": "价格不含 VAT（合计 20%：15% VAT、2.5% NHIL、2.5% GETFund），也不含按实际成本收取的政府及监管机构费用。首次通话始终免费。 费用不包含快递、差旅、住宿、公证和翻译费用；这些费用在您批准后按实际成本收取。",
  "Fixed prices in Ghana cedis, excluding VAT where it applies. Hosting, WhatsApp and phone-call charges from providers are passed on at cost. Every project starts with a free 30-minute call. Courier, travel, accommodation, notary and translation costs are not included and are billed at cost, after your approval.": "固定价格以加纳塞地计，适用增值税时除外。来自服务商的主机、WhatsApp 及电话通话费用按实际成本转嫁。每个项目均以一次免费的 30 分钟通话开始。快递、差旅、住宿、公证及翻译费用不包含在内，将在您批准后按实际成本计费。",
  "USD 1,450": "USD 1,450",
