  "Chatbot speech is generated by AI, rather than a live human speaker. Arabic speech uses Supertonic 3. By using that voice service, you agree to comply with paragraph 5 and Attachment A of the": "聊天机器人的语音由人工智能生成，并非真人实时发声。阿拉伯语语音采用 Supertonic 3。使用该语音服务，即表示您同意遵守以下许可协议的第 5 条和附件 A：",
