  "7 October 2026": "2026年10月7日",
  "Company registration for foreign owners: USD 1,450 all-in (government fees, express filing, TIN, VAT); Ghanaian owners GHS 2,400 plus registry fees. Courier, travel, notary and translation costs are extra, at cost. Approved 7 October 2026.": "外籍业主公司注册：USD 1,450 全包（政府费用、加急申报、TIN、VAT）；加纳籍业主为 GHS 2,400，另加登记费用。快递、差旅、公证和翻译费用另按实际成本收取。于 2026年10月7日批准。",
  "Gotham Consult manages the full sequence, from name search and incorporation to GIPA registration, TIN, VAT and SSNIT, and coordinates sector licences and permits. For registration only, fully remote, our Company registration for foreign owners costs USD 1,450 all-in, including government fees, 48-hour express filing, TIN and VAT; the Ghana-resident director, company secretary and registered office the law requires can be your own or ours. For the full setup, our Market entry and company setup service starts from GHS 32,500 plus government fees. Courier, travel, notary and translation costs are billed at cost. If you are still weighing your options, a Ghana briefing costs GHS 2,900 and is credited against follow-on work.": "Gotham Consult 管理从名称查询、公司设立，到 GIPA 注册、TIN、VAT 和 SSNIT 的全过程，并协调行业许可和审批。若仅需公司注册，我们为外籍业主提供全程远程办理服务，费用为 USD 1,450 全包，包含政府费用、48 小时加急申报、TIN 和 VAT；法律要求的加纳常驻董事、公司秘书及注册地址可由您自行提供，也可由我们提供。完整的市场进入与公司设立服务起价为 GHS 32,500，另加政府费用。快递、差旅、公证及翻译费用按实际成本收取。如果您仍在比较方案，加纳情况介绍咨询费用为 GHS 2,900，可抵扣后续服务费用。",
  "Research for investors in Ghana: economic publications, exchange rates, company share-price histories, sector outlooks and market entry with a local desk.": "面向加纳投资者的研究资料：经济报告、汇率、公司股价历史及行业前景，配合本地办事处的市场进入支持。",
