  "Gotham Consult manages the full sequence, from name search and incorporation to GIPA registration, TIN, VAT and SSNIT, and coordinates sector licences and permits. Our Market entry and company setup service starts from GHS 45,000 plus government fees. If you are still weighing your options, a Ghana briefing costs GHS 6,500 and is credited against follow-on work.": "Gotham Consult管理完整流程，从名称查询和注册到 GIPA 注册、税号、VAT 和 SSNIT，并协调行业许可证和许可。我们的市场准入和公司设立服务起价为 GHS 45,000 加上政府费用。如您仍在权衡选项，Ghana 简报费用为 GHS 6,500，并可抵扣后续工作。",
  "Gotham Consult reviews existing registrations against Act 1173, handles GIPA registration and renewal, and registers technology transfer agreements. For a structured view of how the new law affects your plans, a Ghana briefing costs GHS 6,500 and is credited against follow-on work.": "Gotham Consult 根据第 1173 条法案审查现有注册，处理 GIPA 注册与续期，并登记技术转让协议。若需了解新法案如何影响您的计划，Ghana 简报费用为 GHS 6,500，并可抵扣后续工作费用。",
  "Gotham Consult's price list (excluding VAT), approved 8 October 2026: e.g. market entry from GHS 45,000, Investor Desk GHS 30,000 a month, Family Desk from GHS 2,400 a month.": "Gotham Consult 价格表（不含 VAT），2026 年 10 月 8 日批准：例如市场准入起价 GHS 45,000，投资者服务台每月 GHS 30,000，Family Desk 每月 GHS 2,400 起。",
