  "Counterparty check": "交易对手核查",
  "Before you send money or sign: we check the seller, company or land in the official registers with our partner lawyers and tell you who owns it and whether it is in court.": "在您汇款或签约之前：我们与合作律师在官方登记册中核查卖方、公司或土地，告诉您其所有人是谁，以及是否涉及诉讼。",
