  "Want a smaller first step? Counterparty check: GHS 7,500 for owners, registration, filings and court cases from the official registers. Enhanced counterparty check: GHS 20,000, adding a visit to the site or office, three reference interviews and a written risk rating.": "想先从小一点的步骤开始？交易对手核查：GHS 7,500，依据官方登记册核查所有人、注册、申报和诉讼情况。加强版交易对手核查：GHS 20,000，另含一次现场或办公室走访、三次背景访谈和书面风险评级。",
